import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps


class FindGapsTests(unittest.TestCase):
    def test_gap_between_two_shifts(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(
            find_gaps(worked, Span(540, 1020)), ["gap 12:00-13:00 (60 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(
            find_gaps([], Span(540, 1020)), ["gap 09:00-17:00 (480 min)"]
        )

    def test_fully_covered(self):
        self.assertEqual(find_gaps([Span(540, 1020)], Span(540, 1020)), [])

    def test_overlapping_and_touching_spans_merge(self):
        worked = [Span(780, 840), Span(660, 780), Span(540, 720)]
        self.assertEqual(
            find_gaps(worked, Span(540, 1020)), ["gap 14:00-17:00 (180 min)"]
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            find_gaps([Span(600, 660)], Span(540, 720)),
            ["gap 09:00-10:00 (60 min)", "gap 11:00-12:00 (60 min)"]
        )

    def test_span_starting_before_opening(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(510, 600)], Span(540, 1020))

    def test_span_ending_after_closing(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(960, 1050)], Span(540, 1020))
